88	    assert(k % QK_K == 0);
89	    const int64_t nb = k / QK_K;
90	
91	    for (int i = 0; i < nb; i++) {
92	
93	        float max = 0;
94	        float amax = 0;
95	        for (int j = 0; j < QK_K; ++j) {
96	            float ax = fabsf(x[j]);
97	            if (ax > amax) {
98	                amax = ax; max = x[j];
99	            }
100	        }
101	        if (!amax) {
102	            y[i].d = 0;
103	            memset(y[i].qs, 0, QK_K);
104	            x += QK_K;
105	            continue;
106	        }
107	        //const float iscale = -128.f/max;
108	        // We need this change for IQ2_XXS, else the AVX implementation becomes very awkward
109	        const float iscale = -127.f/max;
110	        for (int j = 0; j < QK_K; ++j) {
111	            int v = nearest_int(iscale*x[j]);
112	            y[i].qs[j] = MIN(127, v);
113	        }
114	        for (int j = 0; j < QK_K/16; ++j) {
115	            int sum = 0;
116	            for (int ii = 0; ii < 16; ++ii) {
117	                sum += y[i].qs[j*16 + ii];
118	            }
119	            y[i].bsums[j] = sum;
120	        }
121	        y[i].d = 1/iscale;
122	        x += QK_K;
123	    }
