125	void quantize_row_tq1_0_ref(const float * GGML_RESTRICT x, block_tq1_0 * GGML_RESTRICT y, int64_t k) {
126	      assert(k % QK_K == 0);
127	    const int64_t nb = k / QK_K;
128	
129	    for (int64_t i = 0; i < nb; i++) {
130	        float amax = 0.0f; // absolute max
131	
132	        for (int j = 0; j < QK_K; j++) {
133	            const float v = x[j];
134	            amax = MAX(amax, fabsf(v));
135	        }
136	
137	        const float d = amax;
138	        const float id = d ? 1.0f/d : 0.0f;
139	
140	        y[i].d = GGML_FP32_TO_FP16(d);
141	
142	        // 5 elements per byte, along 32 bytes
143	        for (size_t j = 0; j < sizeof(y->qs) - sizeof(y->qs) % 32; j += 32) {
144	            for (size_t m = 0; m < 32; ++m) {
145	                uint8_t q = 0;
146	                for (size_t n = 0; n < 5; ++n) {
147	                    int xi = lroundf(x[m + n*32] * id) + 1; // -1, 0, 1 -> 0, 1, 2
148	                    q *= 3;
149	                    q += xi;
150	                }
151	                // ceiling division (243 == pow(3, 5))
152	                q = ((uint16_t)q * 256 + (243 - 1)) / 243;
153	                y[i].qs[j + m] = q;
154	            }
155	            x += 5*32;
156	        }
157	        // along 16 bytes
158	        for (size_t j = sizeof(y->qs) - sizeof(y->qs) % 32; j < sizeof(y->qs); j += 16) {
159	            for (size_t m = 0; m < 16; ++m) {
160	                uint8_t q = 0;
161	                for (size_t n = 0; n < 5; ++n) {
162	                    int xi = lroundf(x[m + n*16] * id) + 1; // -1, 0, 1 -> 0, 1, 2
163	                    q *= 3;
164	                    q += xi;
165	                }
166	                // ceiling division (243 == pow(3, 5))
167	                q = ((uint16_t)q * 256 + (243 - 1)) / 243;
168	                y[i].qs[j + m] = q;
169	            }
170	            x += 5*16;
171	        }
172	        // 4 elements per byte
173	        for (size_t j = 0; j < sizeof(y->qh); ++j) {
174	            uint8_t q = 0;
175	            for (size_t m = 0; m < 4; ++m) {
176	                // -1, 0, 1 -> 0, 1, 2
177	                int xi = lroundf(x[j + m*sizeof(y->qh)] * id) + 1;
178	                q *= 3;
179	                q += xi;
180	            }
181	            // shift the first value to the most significant trit
182	            q *= 3;
183	            // ceiling division (243 == pow(3, 5))
184	            q = ((uint16_t)q * 256 + (243 - 1)) / 243;
185	            y[i].qh[j] = q;
186	        }
187	        x += 4*sizeof(y->qh);
188	    }
189	}
