            vuint8m1_t pq0_w = __riscv_vle8_v_u8m1(qx_ptr, vl);
            vuint8m1_t pq1_w = __riscv_vmul_vx_u8m1(pq0_w, 3,  vl);
            vuint8m1_t pq2_w = __riscv_vmul_vx_u8m1(pq0_w, 9,  vl);
            vuint8m1_t pq3_w = __riscv_vmul_vx_u8m1(pq0_w, 27,   vl);
            vuint8m1_t pq4_w = __riscv_vmul_vx_u8m1(pq0_w, 81,   vl);

            qx_ptr += 16;

            uint32_t qh;
            memcpy(&qh, x[i].qh, sizeof(qh));
            vuint32m1_t qh_vec_w = __riscv_vmv_v_x_u32m1(qh, vl);
            vuint8m1_t packed_h = __riscv_vreinterpret_v_u32m1_u8m1(qh_vec_w);
            vuint8m1_t shift_vec = __riscv_vle8_v_u8m1(k_shift, vl);
            vuint8m1_t pq5_w = __riscv_vmul_vv_u8m1(packed_h, shift_vec,   vl);

            vuint8m1_t tu0 = __riscv_vnsrl_wx_u8m1(__riscv_vwmulu_vx_u16m2(pq0_w, 3, vl), 8, vl);
            vuint8m1_t tu1 = __riscv_vnsrl_wx_u8m1(__riscv_vwmulu_vx_u16m2(pq1_w, 3, vl), 8, vl);
            vuint8m1_t tu2 = __riscv_vnsrl_wx_u8m1(__riscv_vwmulu_vx_u16m2(pq2_w, 3, vl), 8, vl);
            vuint8m1_t tu3 = __riscv_vnsrl_wx_u8m1(__riscv_vwmulu_vx_u16m2(pq3_w, 3, vl), 8, vl);
            vuint8m1_t tu4 = __riscv_vnsrl_wx_u8m1(__riscv_vwmulu_vx_u16m2(pq4_w, 3, vl), 8, vl);
            vuint8m1_t tu5 = __riscv_vnsrl_wx_u8m1(__riscv_vwmulu_vx_u16m2(pq5_w, 3, vl), 8, vl);


            prod = __riscv_vwmaccsu_vv_i16m2(prod, vy0, tu0, vl);
            prod = __riscv_vwmaccsu_vv_i16m2(prod, vy1, tu1, vl);
            prod = __riscv_vwmaccsu_vv_i16m2(prod, vy2, tu2, vl);
            prod = __riscv_vwmaccsu_vv_i16m2(prod, vy3, tu3, vl);
            prod = __riscv_vwmaccsu_vv_i16m2(prod, vy4, tu4, vl);
            prod = __riscv_vwmaccsu_vv_i16m2(prod, vy5, tu5, vl);
        }

        vint32m1_t vzero32 = __riscv_vmv_v_x_i32m1(0, vl);
        vint32m1_t partial_sum = __riscv_vwredsum_vs_i16m2_i32m1(prod, vzero32, vl);
        sum_i += __riscv_vmv_x_s_i32m1_i32(partial_sum);

        int32_t sum_bsums = 0;
        size_t vl_bsums = 16;
        vint16m1_t bsums_vec = __riscv_vle16_v_i16m1(y[i].bsums, vl_bsums);
        vint32m1_t vzero32_bsums = __riscv_vmv_v_x_i32m1(0, vl_bsums);
        vint32m1_t bsums_sum_vec = __riscv_vwredsum_vs_i16m1_i32m1(bsums_vec, vzero32_bsums, vl_bsums);
        sum_bsums = __riscv_vmv_x_s_i32m1_i32(bsums_sum_vec);

        const float d = GGML_FP16_TO_FP32(x[i].d) * y[i].d;
        sumf += d * (float)(sum_i - sum_bsums);
    }

    *s = sumf;
}
#endif // __riscv_v_intrinsic


void dequantize_row_tq1_0(const block_tq1_0 * GGML_RESTRICT x, float * GGML_RESTRICT y, int64_t k) {
     assert(k % QK_K == 0);
    const int64_t nb = k / QK_K;

    const uint8_t pow3[6] = {1, 3, 9, 27, 81, 243};

    for (int64_t i = 0; i < nb; ++i) {

        const float d = GGML_FP16_TO_FP32(x[i].d);

        for (size_t j = 0; j < sizeof(x->qs) - sizeof(x->qs) % 32; j += 32) {
            for (size_t n = 0; n < 5; ++n) {
                for (size_t m = 0; m < 32; ++m) {
                    uint8_t q = x[i].qs[j + m] * pow3[n];
                    int16_t xi = ((uint16_t) q * 3) >> 8;
                    *y++ = (float) (xi - 1) * d;
                }
            }
        }
        for (size_t j = sizeof(x->qs) - sizeof(x->qs) % 32; j < sizeof(x->qs); j += 16) {
            for (size_t n = 0; n < 5; ++n) {
                for (size_t m = 0; m < 16; ++m) {
                    uint8_t q = x[i].qs[j + m] * pow3[n];
                    int16_t xi = ((uint16_t) q * 3) >> 8;
                    *y++ = (float) (xi - 1) * d;
                }
            }
        }

        for (size_t n = 0; n < 4; ++n) {
            for (size_t j = 0; j < sizeof(x->qh); ++j) {
                uint8_t q = x[i].qh[j] * pow3[n];
                int16_t xi = ((uint16_t) q * 3) >> 8;
                *y++ = (float) (xi - 1) * d;
            }
        }
    }
}

void dequantize_row_q8_K(const block_q8_K * GGML_RESTRICT x, float * GGML_RESTRICT y, int64_t k) {
    assert(k % QK_K == 0);
    const int64_t nb = k / QK_K;

    for (int i = 0; i < nb; i++) {
        for (int j = 0; j < QK_K; ++j) {
            *y++ = x[i].d * x[i].qs[j];
        }
    }
}

// --- Main Test Program ---
#define REPEAT 10

int main() {
    enable_ace();
    __asm__ __volatile__ ( " csrs mstatus,  %0" :: "r"((unsigned long) 1 << 9)       );

    const int n = QK_K * REPEAT;

    float *x_f32 = MALLOC(n * sizeof(float));
    float *y_f32 = MALLOC(n * sizeof(float));

    float *de_x_f32 = MALLOC(n * sizeof(float));
    float *de_y_f32 = MALLOC(n * sizeof(float));

    block_tq1_0 *x_tq1 = MALLOC(n * sizeof(block_tq1_0));
    block_q8_K  *y_q8k = MALLOC(n * sizeof(block_q8_K));

    for (int i = 0; i < n; i++) {
        x_f32[i] = 1.0f;
        y_f32[i] = 1.0f;
    }

    quantize_row_tq1_0_ref(x_f32, x_tq1, n);
    quantize_row_q8_K_ref(y_f32, y_q8k, n);
    printf("Test data generated and quantized.\n\n");


#if defined(__riscv_v_intrinsic)
    float result_rvv;
  unsigned long long rvv_cycle_begin = rdcycle();
#ifdef ACE
    ggml_vec_dot_tq1_0_q8_K_ace_rvv(n, &result_rvv, x_tq1, y_q8k);
#else
    ggml_vec_dot_tq1_0_q8_K_rvv(n, &result_rvv, x_tq1, y_q8k);
#endif
  unsigned long long rvv_cycle_end = rdcycle();
  printf("RVV version cycles: %llu\n", rvv_cycle_end - rvv_cycle_begin);
    printf("RISC-V RVV Result          : %f\n", result_rvv);
#else
    printf("\nRISC-V RVV intrinsics not enabled. Compile with -march=rv64gcv to test the RVV version.\n");
#endif

    FREE(x_f32);
    FREE(y_f32);
    FREE(x_tq1);
    FREE(y_q8k);

    return 0;
}

